<form method="post" action="subscription_quote" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="mode" value="renew"><input type="hidden" name="phase" value="quote"><input type="hidden" name="subscription_id" value="<?= (int)$subscription['id'] ?>"><input type="hidden" name="subscription_version" value="<?= e($version) ?>"><input type="hidden" name="start" value="<?= e($start) ?>"><label>Formule du renouvellement *<select name="plan" required><option value="">Sélectionner</option><?php foreach ($plans as $plan): ?><option value="<?= (int)$plan['id'] ?>|<?= e(PlanService::version($plan)) ?>" <?= (int)$plan['id']===$chosenPlan ? 'selected' : '' ?>><?= e($plan['name'].' · '.(int)$plan['duration_days'].' jours · '.dt($plan['price'])) ?></option><?php endforeach; ?></select></label><label>Promotion facultative<select name="promotion"><option value="">Aucune</option><?php foreach ($promotions as $promo): ?><option value="<?= (int)$promo['id'] ?>|<?= e(SubscriptionPricing::promotionVersion($promo)) ?>"><?= e($promo['code'].' · '.$promo['discount_percent'].' %') ?></option><?php endforeach; ?></select></label><p class="form-hint">La durée comprend le jour de début. Les périodes actives ne peuvent pas se chevaucher ; une formule désactivée ne peut pas être choisie.</p><div class="form-actions"><button class="primary" type="submit">Vérifier le prix</button></div></form><?php endif; ?></section>
